                    <span style={{fontSize:'11px',fontWeight:700,color:ally?'#60a5fa':NATION_BLOC[rid]==='east'?'#ef4444':'#9ca3af'}}>{rname}{ally?' 🤝 ALLY':NATION_BLOC[rid]==='east'?' ⚠':''}</span>
